```yaml
name: Auto-close PRs referencing unready issues

on:
  pull_request:
    types: [opened, reopened, synchronize]

jobs:
  close-unready-pr:
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
      issues: write
      contents: read
    steps:
      - name: Close PRs that reference unready issues
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const body = pr.body || "";
            const issueRefs = [];
            const regex = /(?:https?:\\/\\/[^\\/]+\\/[^\\/]+\\/[^\\/]+\\/issues\\/([0-9]+)|#([0-9]+))/g;
            let match;
            while ((match = regex.exec(body)) !== null) {
              const id = match[1] || match[2];
              if (id) issueRefs.push(id);
            }
            if (issueRefs.length === 0) {
              core.info("No issue references found.");
              return;
            }
            if (issueRefs.length > 1) {
              core.info("Multiple issue references found; skipping.");
              return;
            }
            const issueNumber = issueRefs[0];
            const authorAssoc = pr.author_association;
            const authorType = pr.user.type;
            if (authorAssoc === "MEMBER" || authorAssoc === "OWNER" || authorType === "Bot") {
              core.info(`PR author is ${authorAssoc} or bot; skipping.`);
              return;
            }
            try {
              const { data: issue } = await github.rest.issues.get({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber
              });
              const cutoff = new Date("2026-03-10T00:00:00Z");
              const issueCreated = new Date(issue.created_at);
              if (issueCreated < cutoff) {
                core.info(`Issue #${issueNumber} created before cutoff; skipping.`);
                return;
              }
              const hasReady = issue.labels.some(l => l.name === "ready");
              if (hasReady) {
                core.info(`Issue #${issueNumber} has ready label; no action.`);
                return;
              }
              const commentBody = `🚨 This PR references issue #${issueNumber} which has not yet been triaged (missing the \`ready\` label). Please add the \`ready\` label to the issue before reopening this PR.`;
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                body: commentBody
              });
              await github.rest.pulls.update({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: pr.number,
                state: "closed"
              });
              core.info(`Closed PR #${pr.number} due to unready issue #${issueNumber}.`);
            } catch (error) {
              core.error(`Error processing issue #${issueNumber}: ${error}`);
            }
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
```

